module fsm_machine (
        input clk,
        input reset,
        input i,
        output reg y);parameter E=0, F=1, G=2, H=3;
	reg [1:0] state, next;

	always @(posedge clk)
		if (reset)
			state <= E;
		else 
			state <= next;

	always_comb begin
		case(state)
			E: next = i ? G : F;
			F: next = i ? E : H;
			G: next = i ? H : E;
			H: next = i ? G : F;
			default: next = 'x;
		endcase
	end

	assign y = (state == E || state == G);

endmodule

