description:
Design a finite state machine (FSM) that manages a simple state progression through five defined states: IDLE, S1, S2, S3, and DONE. The FSM transitions from one state to the next on each clock cycle, starting from IDLE and moving sequentially to DONE, while asserting the output 'ack' when the DONE state is reached. Additionally, it includes a mechanism for indicating the current state as an ASCII string representation for debugging or monitoring purposes, allowing the user to easily identify which stage the FSM is currently in. The module is reset asynchronously with a low signal on the reset input.
module top_module(
                             input  clk,
                             input  rst_n,
                             output ack
                             );

code:
module top_module(
                             input  clk,
                             input  rst_n,
                             output ack
                             );localparam 
     IDLE  = 0,
     S1    = 1,
     S2    = 2,
     S3    = 3,
     DONE  = 4;

   reg [4:0] 
             cur_state, nxt_state;

   always @ (*) begin
      nxt_state  = 5'h0;

      case (1'b1)
        cur_state[IDLE] : nxt_state[S1]    = 1'b1;
        cur_state[S1]   : nxt_state[S2]    = 1'b1;
        cur_state[S2]   : nxt_state[S3]    = 1'b1;
        cur_state[S3]   : nxt_state[DONE]  = 1'b1;
        cur_state[DONE] : nxt_state[DONE]  = 1'b1;
      endcase
   end

   always @ (posedge clk or negedge rst_n)
     if (rst_n == 1'b0) begin
        cur_state <= 'h1;
     end
     else begin
        cur_state <= nxt_state;
     end

   assign ack  = cur_state[DONE];



   reg [31:0] cur_state_ascii;  
   always @(cur_state) begin
      case ({cur_state})
        (5'b1<<IDLE):     cur_state_ascii  = "idle";
        (5'b1<<S1):       cur_state_ascii  = "s1  ";
        (5'b1<<S2):       cur_state_ascii  = "s2  ";
        (5'b1<<S3):       cur_state_ascii  = "s3  ";
        (5'b1<<DONE):     cur_state_ascii  = "done";
        default:          cur_state_ascii  = "%Err";
      endcase
   end


endmodule

