module top_module(input clk, reset, double,
               input regWriteEn, jal,
               input [4:0] RsAddr, RtAddr,
               input [4:0] regWriteAddr,
               input [63:0] regWriteData,
               input [31:0] pc,
               output [31:0] RsData, RtData,
               input [4:0] switch,
               output [15:0] regtoshow);reg [31:0] rf [31:0];
    reg [31:0] hi, lo;
    integer i;
    always @ (posedge clk)
        begin
            if(reset)
                for(i = 0; i < 32; i = i + 1)
                    rf[i] = 0;
            if(regWriteEn)
                begin
                    if(double)
                        {hi, lo} <= regWriteData;
                    else
                        rf[regWriteAddr] <= regWriteData[31:0];
                end
            if(jal) rf[31] <= pc;
        end

    assign regtoshow = rf[switch][15:0];
    assign RsData = (RsAddr != 0) ? rf[RsAddr] : 0;
    assign RtData = (RtAddr != 0) ? rf[RtAddr] : 0;
endmodule

