module priority_encoder (
    input en,
    input [3:0] in,
    output reg [1:0] out);always @(*) begin
        if (en) begin
            casex (in)
                4'b1xxx: out = 2'b11;
                4'b01xx: out = 2'b10;
                4'b001x: out = 2'b01;
                4'b0001: out = 2'b00;
                default: out = 2'b00;
            endcase
        end else begin
            out = 2'b00;
        end
    end

endmodule

