module top_module (
        input clk,
        input areset,
        input x,
        output reg z);parameter Init=2'b00, Count=2'b01, Done=2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Init;
		else begin
			case (state)
				Init: state <= x ? Count : Init;
				Count: state <= x ? Count : Done;
				Done: state <= x ? Init : Done;
			endcase
		end
	end

	assign z = (state == Count);

endmodule

