module alarm_system_controller (
        input clk,
        input areset,
        input arm,
        input disarm,
        output reg alarm);parameter Alarm_Disarmed=1'b0, Alarm_Armed=1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Alarm_Disarmed;
		else begin
			case (state)
				Alarm_Disarmed: state <= arm ? Alarm_Armed : Alarm_Disarmed;
				Alarm_Armed: state <= disarm ? Alarm_Disarmed : Alarm_Armed;
			endcase
		end
	end

	assign alarm = (state == Alarm_Armed);

endmodule

