description:
Design a D-type flip-flop with an enable input. The output Q is updated to the value of input D on the rising edge of the clock signal C, but only if the enable signal E is asserted. This module includes timing specifications tailored for different FPGA families, ensuring proper setup and hold timing for reliable operation in various conditions.
module top_module(
    output reg Q,
    input C, E, D
);

code:
module top_module(
    output reg Q,
    input C, E, D
);// Initialize flip-flop
    always @ (posedge C) begin
        if (E) begin
            Q <= D;
        end
    end

    // Timing specifications for ICE40_HX
    `ifdef ICE40_HX
    specify
        $setup(D, posedge C &&& E, 470 - 449);
        $setup(E, posedge C, 0);
        if (E) (posedge C => (Q : D)) = 540;
    endspecify
    `endif

    // Timing specifications for ICE40_LP
    `ifdef ICE40_LP
    specify
        $setup(D, posedge C &&& E, 693 - 662);
        $setup(E, posedge C, 0);
        if (E) (posedge C => (Q : D)) = 796;
    endspecify
    `endif

    // Timing specifications for ICE40_U
    `ifdef ICE40_U
    specify
        $setup(D, posedge C &&& E, 0); // Negative times not currently supported
        $setup(E, posedge C, 0);
        if (E) (posedge C => (Q : D)) = 1391;
    endspecify
    `endif

endmodule

