module top_module (
        input clk,
        input areset,
        input sensor,
        input timer,
        output reg [1:0] light);parameter Red=2'b00, Green=2'b01, Yellow=2'b10;
	reg [1:0] state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Red;
		else begin
			case (state)
				Red: state <= sensor ? Green : Red;
				Green: state <= timer ? Green : Yellow;
				Yellow: state <= timer ? Yellow : Red;
			endcase
		end
	end

	assign light = (state == Red) ? 2'b00 :
	               (state == Green) ? 2'b01 :
	               (state == Yellow) ? 2'b10 : 2'b00;

endmodule

