module parity_generator (
    input clk,
    input serial_in,
    output reg parity
);

    reg [8:0] shift_reg;

    always @(posedge clk) begin
        shift_reg <= {serial_in, shift_reg[8:1]};
        parity <= ^shift_reg; // XOR all bits in shift_reg
    end

endmodule

