    begin
      if(pulse_counter == 0)
      begin
        pulse_generated <= 1'b0;
      end
      else
      begin
        pulse_counter <= pulse_counter - 1'b1;
      end
    end

    if(int_enbl_wire)
    begin
      int_cntr_next = int_cntr_reg - 1'b1;
    end
  end

  assign s_axis_tready = int_tready_wire;
  assign m_axis_tdata = s_axis_tdata[15:0];
  assign m_axis_tvalid = int_tvalid_wire;

