module top_module(
  input               clk,
  input               rst_n,
  input               a,
  output reg          rise,
  output reg          down
);// Define states for state machine
  parameter IDLE = 2'b00;
  parameter RISING = 2'b01;
  parameter FALLING = 2'b10;

  // Define current state and next state variables
  reg [1:0] state, next_state;

  // Define edge detection variables
  reg a_prev;
  wire a_xor;

  // Assign next state based on current state and edge detection
  always @ (posedge clk or negedge rst_n) begin
    if (~rst_n) begin
      state <= IDLE;
    end else begin
      state <= next_state;
    end
  end

  // Perform edge detection and assign next state
  assign a_xor = a ^ a_prev;
  always @ (*) begin
    case (state)
      IDLE: begin
        if (a_xor) begin
          if (a) begin
            next_state = RISING;
          end else begin
            next_state = FALLING;
          end
        end else begin
          next_state = IDLE;
        end
      end
      RISING: begin
        next_state = IDLE;
      end
      FALLING: begin
        next_state = IDLE;
      end
    endcase
  end

  // Assign output signals based on current state
  always @ (*) begin
    case (state)
      IDLE: begin
        rise <= 1'b0;
        down <= 1'b0;
      end
      RISING: begin
        rise <= 1'b1;
        down <= 1'b0;
      end
      FALLING: begin
        rise <= 1'b0;
        down <= 1'b1;
      end
    endcase
    a_prev <= a;
  end

endmodule

