description:
Develop a variable frequency oscillator (VCO) interface that generates an output clock signal based on a control voltage and a reference clock. The circuit increments a counter with each rising edge of the reference clock, and when the counter reaches a threshold determined by the control voltage (scaled by a factor of 100), it resets and toggles the output clock signal. This effectively allows the output frequency to be modulated by the control voltage input, giving a tunable frequency output.
module top_module(
  input control_voltage,
  input ref_clock,
  output reg out_clock  // changed from wire to reg
);

code:
module top_module(
  input control_voltage,
  input ref_clock,
  output reg out_clock  // changed from wire to reg
);reg [31:0] counter;
  reg [31:0] threshold;

  always @ (posedge ref_clock) begin
    if (counter >= threshold) begin
      counter <= 0;
      out_clock <= ~out_clock;
    end else begin
      counter <= counter + 1;
    end
  end

  always @ (control_voltage) begin
    threshold <= control_voltage * 100;
  end

endmodule

